/* 
  Conceptual Circuit Breaker Logic
*/

let consecutiveFailures = 0;
let isCircuitOpen = false;

async function safeFetchRecommendations() {
  if (isCircuitOpen) {
    // INSTANTLY return a fallback to save server resources.
    // Don't even try to make the HTTP request!
    return { data: [], message: "Recommendations temporarily offline" };
  }

  try {
    const res = await fetch('http://flaky-recommendation-service/api');
    consecutiveFailures = 0; // Success! Reset counter.
    return res.json();
  } catch (error) {
    consecutiveFailures++;

    if (consecutiveFailures > 5) {
      console.error("SERVICE IS DEAD. TRIPPING CIRCUIT BREAKER!");
      isCircuitOpen = true;

      // Automatically try to heal in 60 seconds (Transition to Half-Open)
      setTimeout(() => { isCircuitOpen = false; }, 60000);
    }
    throw error;
  }
}
